import{GUIDE as r,BRAND as c}from"./copy.min.js";import{presetFor as f}from"./sheet.min.js";import{priceChoice as p,formatMoney as i}from"./pricing.min.js";export const GUIDED=Object.freeze(["floors","firstRoom","added","dots","rooms","review"]),PROGRESS=Object.freeze({floors:0,firstRoom:1,added:1,dots:1,rooms:2,review:3});const d=["hint","about"],m=GUIDED;export function arrivalId(n){const s=(n.checklists||[]).filter(u=>!u.deletedAt),e=s.find(u=>u.id===n.settings.activeId);if(e)return e.id;const t=s.filter(u=>!u.sample).sort((u,l)=>String(l.updatedAt).localeCompare(String(u.updatedAt)));if(t.length)return t[0].id;const o=s.find(u=>u.sample);return o?o.id:null}export function hasOwn(n){return(n.checklists||[]).some(s=>!s.deletedAt&&!s.sample)}export function arrivalGuide(n){const s=n.settings&&n.settings.guide,e=!!(s&&s.reviewed);return hasOwn(n)?{scene:"welcome",resume:s&&GUIDED.includes(s.scene)?s.scene:null,reviewed:e,back:null,tapped:!1,rooms:0}:{scene:"hello",resume:null,reviewed:e,back:null,tapped:!1,rooms:0}}export function savedForm(n){return{scene:GUIDED.includes(n.scene)?n.scene:n.scene==="welcome"&&n.resume?n.resume:"done",reviewed:!!n.reviewed}}export function step(n,s){const e=n,t=(u,l={})=>({...e,scene:u,...l}),o=s&&s.type;if(o==="restart")return t("hello",{back:null,tapped:!1,rooms:0,resume:null});if(o==="about")return d.includes(e.scene)?e:t("about",{back:e.scene});if(o==="again")return e.scene==="done"||e.scene==="look"||e.scene==="saved"?t("hint",{back:e.scene}):e;if(o==="close"&&d.includes(e.scene))return t(e.back||"done",{back:null});if(o==="skip"&&m.includes(e.scene))return t("done");if(o==="homeMade"&&["hello","example1","example2","example3","look"].includes(e.scene))return t("firstRoom");switch(e.scene){case"hello":return o==="start"?t("floors",{tapped:!1}):o==="example"?t("example1"):e;case"floors":return o==="floorTapped"?e.tapped?e:t("floors",{tapped:!0}):o==="next"?t("firstRoom"):o==="roomAdded"?t("added",{roomId:s.roomId||null}):e;case"firstRoom":return o==="roomAdded"?t("added",{roomId:s.roomId||null}):e;case"added":return o==="next"?t("dots"):o==="dotOpened"?t("rooms"):o==="roomAdded"?t("rooms",{rooms:e.rooms+1}):e;case"dots":return o==="gotIt"||o==="dotOpened"?t("rooms"):o==="roomAdded"?t("rooms",{rooms:e.rooms+1}):e;case"rooms":return o==="roomAdded"?t("rooms",{rooms:e.rooms+1}):o==="review"?t("review"):e;case"review":return o==="saved"?t("saved",{reviewed:!0}):e;case"saved":return o==="lookAround"?t("done"):e;case"example1":return o==="next"?t("example2"):e;case"example2":return o==="next"?t("example3"):e;case"example3":case"look":return o==="buildOwn"?t("floors",{tapped:!1}):o==="lookAround"&&e.scene==="example3"?t("look"):e;case"welcome":return o==="keepGoing"&&e.resume?t(e.resume,{resume:null}):o==="lookAround"?t("done",{resume:null}):e;default:return e}}export function presetSummary(n,s){if(!n)return null;const e=f(n,s);let t=0,o=0,u=0;for(const l of e){const a=p(n,l,s);a.error||(t+=a.cents,o+=a.minutes,u++)}return{count:u,cents:t,minutes:o}}export function addedLine(n,s,e){const t=String(e||"").toLowerCase(),o=presetSummary(n,s);if(!o||!o.count)return r.addedPlain(t);const u=r.added(t,o.count,i(o.cents)),l=n.visitMinimumCents||0;return o.cents<l?`${u} ${r.addedMinimum(i(l))}`:u}export function viewFor(n,s={}){const e=(o,u,l=!1)=>({id:o,label:u,primary:l}),t={choices:null,progress:PROGRESS[n.scene]??null,skip:m.includes(n.scene),small:"",again:r[`${n.scene}Again`]||""};switch(n.scene){case"hello":return{...t,text:r.hello,buttons:[e("start",r.start,!0),e("example",r.example)],small:c.honesty};case"floors":return{...t,text:n.tapped?`${r.floorsTaking} ${r.floors}`:r.floors,buttons:[e("next",r.next,!0)],choices:"floors"};case"firstRoom":return{...t,text:r.firstRoom,buttons:[e("kitchen",r.addKitchen,!0),e("otherRoom",r.otherRoom)]};case"added":return{...t,text:s.addedText||r.addedPlain(String(s.roomLabel||"").toLowerCase()),buttons:[e("next",r.next,!0)]};case"dots":return{...t,text:r.dots,buttons:[e("gotIt",r.gotIt)]};case"rooms":{const o=[e("addRoom",r.addRoom,!0)];return(s.roomCount||0)>=2&&o.push(e("review",r.reviewIt)),{...t,text:n.rooms>=2?r.roomsMore:r.rooms,buttons:o}}case"review":return{...t,text:r.review,buttons:[e("save",r.save,!0),e("preferences",r.preferences)]};case"saved":return{...t,text:r.saved,buttons:[e("lookAround",r.lookAround,!0)]};case"example1":return{...t,text:r.example1,buttons:[e("next",r.next,!0)]};case"example2":return{...t,text:r.example2,buttons:[e("next",r.next,!0)]};case"example3":return{...t,text:r.example3,buttons:[e("buildOwn",r.buildOwn,!0),e("lookAround",r.lookAround)]};case"look":return{...t,text:r.look,buttons:[e("buildOwn",r.buildOwn,!0)]};case"welcome":return n.resume?{...t,text:r.welcomeResume,buttons:[e("keepGoing",r.keepGoing,!0),e("lookAround",r.illLook)]}:{...t,text:r.welcome,buttons:[e("lookAround",r.lookAround,!0)]};case"hint":return{...t,text:r.hint,buttons:[e("close",r.gotIt,!0)]};case"about":return{...t,text:r.about,buttons:[e("close",r.close,!0)],small:c.honesty};default:return null}}
